"use client";

import { useState } from "react";
import { createClient } from "@/lib/supabase/client";
import { useRouter } from "next/navigation";

export default function Onboarding() {

  const supabase = createClient();
  const router = useRouter();

  const [businessName, setBusinessName] = useState("");
  const [phone, setPhone] = useState("");
  const [address, setAddress] = useState("");
  const [radius, setRadius] = useState("20");

  const [message, setMessage] = useState("");


  async function createBusiness(){

    const {
      data:{user}
    } = await supabase.auth.getUser();


    if(!user){
      setMessage("You must be logged in");
      return;
    }


    const slug = businessName
      .toLowerCase()
      .replaceAll(" ","-");


    const {error} = await supabase
      .from("groomers")
      .insert({
        user_id:user.id,
        business_name:businessName,
        slug,
        phone,
        address,
        service_radius_miles:Number(radius)
      });


    if(error){
      setMessage(error.message);
      return;
    }


    router.push("/services");

  }


  return (

    <main className="min-h-screen bg-green-50 flex items-center justify-center p-6">

      <div className="bg-white p-8 rounded-3xl shadow w-full max-w-xl">

        <h1 className="text-3xl font-bold mb-6">
          🐾 Create Your Grooming Business
        </h1>


        <input
        className="border p-3 rounded-xl w-full mb-3"
        placeholder="Business Name"
        onChange={(e)=>setBusinessName(e.target.value)}
        />


        <input
        className="border p-3 rounded-xl w-full mb-3"
        placeholder="Phone"
        onChange={(e)=>setPhone(e.target.value)}
        />


        <input
        className="border p-3 rounded-xl w-full mb-3"
        placeholder="Address"
        onChange={(e)=>setAddress(e.target.value)}
        />


        <input
        className="border p-3 rounded-xl w-full mb-4"
        placeholder="Service Radius (miles)"
        type="number"
        value={radius}
        onChange={(e)=>setRadius(e.target.value)}
        />


        <button
        onClick={createBusiness}
        className="bg-green-600 text-white w-full py-3 rounded-xl"
        >
          Create Business
        </button>


        {message && (
          <p className="mt-4 text-center text-red-500">
            {message}
          </p>
        )}

      </div>

    </main>

  );

}